<?php
declare(strict_types=1);namespace Joomleague\Module\Spotlight\Site\Helper;defined('_JEXEC')or die;use Joomla\CMS\Factory;use Joomla\Database\DatabaseInterface;use Joomla\Registry\Registry;use Joomleague\Component\Joomleague\Domain\Service\SpotlightReader;final class SpotlightHelper{/** @return array<string,mixed> */public function getSpotlight(Registry$p):array{try{$app=Factory::getApplication();$app->bootComponent('com_joomleague');$levels=$app->getIdentity()?->getAuthorisedViewLevels()??[1];$kind=in_array((string)$p->get('entity_type','person'),['person','team'],true)?(string)$p->get('entity_type','person'):'person';$automatic=(string)$p->get('selection_mode','automatic')==='automatic';$id=$kind==='person'?(int)$p->get('person_id',0):(int)$p->get('team_id',0);$item=(new SpotlightReader(Factory::getContainer()->get(DatabaseInterface::class)))->read($kind,$id,$automatic,Factory::getDate()->format('Y-m-d',true),$levels);if(!$item)return['error'=>'MOD_JOOMLEAGUE_SPOTLIGHT_EMPTY'];$item->excerpt=mb_substr(trim(strip_tags((string)($item->description??''))),0,max(40,min(500,(int)$p->get('description_length',180))));return['item'=>$item];}catch(\Throwable){return['error'=>'MOD_JOOMLEAGUE_SPOTLIGHT_UNAVAILABLE'];}}}
